"pm.test("Status code is 200", function () { pm.response.to.have.status(200); });
const apps = pm.response.json().data.applications;
pm.test("Applicant details are populated (no password)", function () {
  pm.expect(apps[0].applicant).to.have.property("email");
  pm.expect(apps[0].applicant).to.not.have.property("password");
});"

"pm.test("Status code is 200", function () { pm.response.to.have.status(200); });
pm.test("Cookie is cleared by the server", function () {
  const c = pm.response.headers.get("Set-Cookie") || "";
  pm.expect(c).to.include("token=;");
});"
